// Writes the app's stylesheet, public/app.css, from Storybook's sources:
// styles/tokens.css (generated from tokens/tokens.json) followed by styles/garden.css.
// Run `npm run tokens` first (`npm run app-css` does both).
import { readFileSync, writeFileSync } from 'node:fs';

const root = new URL('../', import.meta.url);
const tokensCss = readFileSync(new URL('styles/tokens.css', root), 'utf8');
const gardenCss = readFileSync(new URL('styles/garden.css', root), 'utf8');

const header = [
  '/* Generated by storybook/scripts/build-app-css.js — do not edit.',
  '   Change storybook/tokens/tokens.json or storybook/styles/garden.css, then run `npm run app-css` in storybook/. */',
  '',
  ':root { color-scheme: light; }',
  '',
].join('\n');

const appCssUrl = new URL('../public/app.css', root);
writeFileSync(appCssUrl, `${header}${tokensCss}\n${gardenCss}`);
console.log(`app.css written: ${appCssUrl.pathname}`);
